def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check if all digits are '9'
    if all(ch == '9' for ch in s):
        # Next palindrome after 999...9 is 1000...0001
        return int('1' + ('0' * (length - 1)) + '1')

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def mirror_left_to_right(x: str) -> str:
        half = length // 2
        if length % 2 == 0:
            return x[:half] + x[:half][::-1]
        else:
            return x[:half+1] + x[:half][::-1]

    # If input itself is palindrome, next palindrome must be strictly greater
    # So start from n+1
    num = n + 1
    s = str(num)
    length = len(s)

    while True:
        if is_palindrome(s):
            return int(s)
        # Construct palindrome by mirroring left to right
        p = mirror_left_to_right(s)
        if int(p) >= num:
            return int(p)
        # If palindrome formed is smaller, increment the middle part and mirror again
        s_list = list(s)
        mid = (length - 1) // 2
        # Increment the middle digit(s)
        left_end = (length // 2) if (length % 2 == 0) else (mid + 1)

        # Increment the left half + middle as a number, then mirror
        left_part = s[:left_end]
        incremented = str(int(left_part) + 1)
        if len(incremented) > len(left_part):  # length increased, e.g. 999 +1 = 1000
            # Example: 999 -> after increment left part become 1000, length increased by 1
            # So palindrome length increases by 1
            length += 1
            s = '1' + ('0' * (length - 2)) + '1'
            num = int(s)
            return num
        else:
            if length % 2 == 0:
                s = incremented + incremented[::-1]
            else:
                s = incremented + incremented[:-1][::-1]
            num = int(s)

