    if not arr:
        return True

    n = len(arr)
    # Check if arr is already non-decreasing
    def is_sorted(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    if is_sorted(arr):
        return True

    # Try all possible right shifts and check if sorted
    # Right shift by k means last k elements move to front
    for k in range(1, n):
        shifted = arr[-k:] + arr[:-k]
        if is_sorted(shifted):
            return True

    return False

