def anti_shuffle(s):
    # Split the string into words and spaces, preserving all parts
    parts = re.findall(r'\S+|\s+', s)

    result = []
    for part in parts:
        if part.isspace():
            # Keep spaces as is
            result.append(part)
        else:
            # Sort all characters (including punctuation) by ASCII value
            sorted_part = ''.join(sorted(part))
            result.append(sorted_part)
    return ''.join(result)

